def solve_parenthesis_problem(length, s):
    # Initialize the stack to keep track of unmatched '(' and their positions
    stack = []
    result = list(s)

    # First pass: try to match parentheses and remove valid ones
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                # Unmatched ')' found, mark it as invalid
                result[i] = '?'

    # Second pass: handle remaining unmatched '(' and '?' characters
    while stack:
        pos = stack.pop()
        if pos < length - 1 and result[pos + 1] != '?':
            # Replace a '?' before or after the last unmatched '('
            result[pos] = '?'
        else:
            # If no valid position found, return ":("
            return ':('

    # Check if the resulting sequence is a correct parenthesis sequence
    balance = 0
    for char in ''.join(result).replace('?', ''):
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return ':('

    return ''.join(result)

