def solve(s):
    n = len(s)
    if n % 2 == 1 or s.count('?') != 1:
        return ":("

    index_of_question_mark = s.index('?')
    if index_of_question_mark == 0 or index_of_question_mark == n - 1:
        return ":("

    left_part = s[:index_of_question_mark]
    right_part = s[index_of_question_mark + 1:]

    stack = []
    for char in left_part[::-1]:
        if char == '(':
            stack.append(char)
        elif stack:
            stack.pop()

    if stack:
        return ":("

    stack = []
    for char in right_part:
        if char == ')':
            stack.append(char)
        elif stack:
            stack.pop()

    if stack:
        return ":("

    return left_part + ')' + right_part

